   "id": "s-coverage-rule",
   "kind": "solution",
   "title": "Define when a test exercises a condition",
   "short": "",
   "order": 0,
   "parent": "",
   "status": "proposed",
   "severity": "",
   "found": "",
   "related": [],
   "causedBy": [],
