   "id": "valafter-pitfall",
   "kind": "problem",
   "title": "It is easy to write Val where ValAfter is meant",
   "short": "",
   "order": 0,
   "parent": "timing-convention",
   "status": "open",
   "severity": "minor",
   "found": "2026-10-05",
